"""Generate a local .env with strong random secrets (spec 19.7 `make env`). Never overwrites.

VAPID keys (Web Push) are generated later (Phase 8) when pywebpush is added; placeholders are not
written so nothing can mistake them for real keys.
"""

from __future__ import annotations

import contextlib
import secrets
import sys
from pathlib import Path

ENV = Path(__file__).resolve().parents[2] / ".env"


def main() -> int:
    if ENV.exists():
        sys.stdout.write(".env already exists; not overwriting\n")
        return 0
    lines = [
        "# Generated by `make env`. Never commit this file.",
        f"POSTGRES_PASSWORD={secrets.token_urlsafe(24)}",
        f"REDIS_PASSWORD={secrets.token_urlsafe(24)}",
        f"MINIO_ROOT_USER=cg{secrets.token_hex(4)}",
        f"MINIO_ROOT_PASSWORD={secrets.token_urlsafe(24)}",
        f"SECRET_KEY={secrets.token_urlsafe(48)}",
        f"METRICS_TOKEN={secrets.token_urlsafe(24)}",
        "",
    ]
    ENV.write_text("\n".join(lines), encoding="utf-8")
    with contextlib.suppress(OSError):  # Windows uses ACLs, not POSIX modes
        ENV.chmod(0o600)
    sys.stdout.write("wrote .env with fresh secrets\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
